  "circle-steps": "'use client';\n\nimport React from 'react';\nimport { Flex, Progress, Slider, Typography } from '@ceebee/ui/client';\n\nconst App: React.FC = () => {\n  const [stepsCount, setStepsCount] = React.useState<number>(5);\n  const [stepsGap, setStepsGap] = React.useState<number>(7);\n  return (\n    <>\n      <Typography.Title level={5}>Custom count:</Typography.Title>\n      <Slider min={2} max={10} value={stepsCount} onChange={setStepsCount} />\n      <Typography.Title level={5}>Custom gap:</Typography.Title>\n      <Slider step={4} min={0} max={40} value={stepsGap} onChange={setStepsGap} />\n      <Flex wrap gap=\"medium\" style={{ marginTop: 16 }}>\n        <Progress\n          type=\"dashboard\"\n          steps={8}\n          percent={50}\n          railColor=\"rgba(0, 0, 0, 0.06)\"\n          strokeWidth={20}\n        />\n        <Progress\n          type=\"circle\"\n          percent={100}\n          steps={{ count: stepsCount, gap: stepsGap }}\n          railColor=\"rgba(0, 0, 0, 0.06)\"\n          strokeWidth={20}\n        />\n      </Flex>\n    </>\n  );\n};\n\nexport default App;\n",
  "circle": "'use client';\n\nimport React from 'react';\nimport { Flex, Progress } from '@ceebee/ui/client';\n\nconst App: React.FC = () => (\n  <Flex gap=\"small\" wrap>\n    <Progress type=\"circle\" percent={75} />\n    <Progress type=\"circle\" percent={70} status=\"exception\" />\n    <Progress type=\"circle\" percent={100} />\n  </Flex>\n);\n\nexport default App;\n",
  "dashboard": "'use client';\n\nimport React, { useState } from 'react';\nimport { Flex, Progress, Segmented } from '@ceebee/ui/client';\nimport type { ProgressProps } from '@ceebee/ui/client';\n\ntype GapPlacement = NonNullable<ProgressProps['gapPlacement']>;\n\nconst App: React.FC = () => {\n  const [gapPlacement, setGapPlacement] = useState<GapPlacement>('bottom');\n  const [gapDegree, setGapDegree] = useState<number>(50);\n  return (\n    <Flex vertical gap=\"large\">\n      <div>\n        gapDegree:\n        <Segmented\n          options={[\n            { label: 50, value: 50 },\n\n            { label: 100, value: 100 },\n          ]}\n          defaultValue={50}\n          onChange={(value: number) => {\n            setGapDegree(value);\n          }}\n        />\n      </div>\n      <div>\n        gapPlacement:\n        <Segmented\n          options={[\n            { label: 'start', value: 'start' },\n            { label: 'end', value: 'end' },\n            { label: 'top', value: 'top' },\n            { label: 'bottom', value: 'bottom' },\n          ]}\n          defaultValue=\"bottom\"\n          onChange={(value: GapPlacement) => {\n            setGapPlacement(value);\n          }}\n        />\n      </div>\n      <Progress type=\"dashboard\" gapDegree={gapDegree} percent={30} gapPlacement={gapPlacement} />\n    </Flex>\n  );\n};\n\nexport default App;\n",
  "dynamic": "'use client';\n\nimport React, { useState } from 'react';\nimport { MinusOutlined, PlusOutlined } from '@ant-design/icons';\nimport { Button, Flex, Progress, Space } from '@ceebee/ui/client';\n\nconst App: React.FC = () => {\n  const [percent, setPercent] = useState<number>(0);\n\n  const increase = () => {\n    setPercent((prevPercent) => {\n      const newPercent = prevPercent + 10;\n      if (newPercent > 100) {\n        return 100;\n      }\n      return newPercent;\n    });\n  };\n\n  const decline = () => {\n    setPercent((prevPercent) => {\n      const newPercent = prevPercent - 10;\n      if (newPercent < 0) {\n        return 0;\n      }\n      return newPercent;\n    });\n  };\n\n  return (\n    <Flex vertical gap=\"small\">\n      <Flex vertical gap=\"small\">\n        <Progress percent={percent} type=\"line\" />\n        <Progress percent={percent} type=\"circle\" />\n      </Flex>\n      <Space.Compact>\n        <Button onClick={decline} icon={<MinusOutlined />} />\n        <Button onClick={increase} icon={<PlusOutlined />} />\n      </Space.Compact>\n    </Flex>\n  );\n};\n\nexport default App;\n",
